from typing import Dict, Any, List

from checkov.common.models.enums import CheckCategories, CheckResult
from checkov.common.util.type_forcers import force_list
from checkov.terraform.checks.resource.base_resource_check import BaseResourceCheck


class WAFACLCVE202144228(BaseResourceCheck):
    def __init__(self) -> None:
        name = "Ensure WAF prevents message lookup in Log4j2. See CVE-2021-44228 aka log4jshell"
        id = "CKV_AWS_192"
        supported_resources = ["aws_wafv2_web_acl"]
        categories = [CheckCategories.APPLICATION_SECURITY]
        super().__init__(name=name, id=id, categories=categories, supported_resources=supported_resources)

    def scan_resource_conf(self, conf: Dict[str, Any]) -> CheckResult:
        self.evaluated_keys = ["rule"]
        rules = conf.get("rule") or []

        # normalize to list without importing heavy helpers
        if not isinstance(rules, list):
            rules = [rules]

        found_definitive_pass = False
        found_definitive_fail = False
        ambiguous = False

        for idx_rule, rule in enumerate(rules):
            if not isinstance(rule, dict):
                ambiguous = True
                continue

            self.evaluated_keys = [f"rule/[{idx_rule}]/statement"]
            statement = rule.get("statement")
            if not statement:
                # if there's no statement, we can't determine compliance for this rule
                ambiguous = True
                continue

            if not isinstance(statement, list):
                # dynamic/placeholder case previously resulted in UNKNOWN
                ambiguous = True
                continue

            # iterate over all statements, as some may be placeholders (e.g., integers)
            managed_groups: List[Dict[str, Any]] = []
            for st_idx, st in enumerate(statement):
                if isinstance(st, dict):
                    mg = st.get("managed_rule_group_statement")
                    if isinstance(mg, list) and mg and isinstance(mg[0], dict):
                        managed_groups.append(mg[0])
                else:
                    ambiguous = True

            # evaluate managed rule groups for KnownBadInputs
            for mg_idx, mg0 in enumerate(managed_groups):
                name = mg0.get("name") if isinstance(mg0, dict) else None
                if name == ["AWSManagedRulesKnownBadInputsRuleSet"]:
                    self.evaluated_keys = [
                        f"rule/[{idx_rule}]/statement/[{mg_idx}]/managed_rule_group_statement/[0]/name"
                    ]
                    excluded_rules = mg0.get("excluded_rule") or []

                    # if excluded rules contain Log4JRCE -> definitive FAIL
                    if isinstance(excluded_rules, list):
                        for idx_excluded_rule, ex in enumerate(excluded_rules):
                            if isinstance(ex, dict) and ex.get("name") == ["Log4JRCE"]:
                                self.evaluated_keys = [
                                    f"rule/[{idx_rule}]/statement/[0]/managed_rule_group_statement/[0]/name",
                                    f"rule/[{idx_rule}]/statement/[0]/managed_rule_group_statement/[0]/excluded_rule/[{idx_excluded_rule}]/name",
                                ]
                                return CheckResult.FAILED
                            if not isinstance(ex, dict):
                                ambiguous = True
                    else:
                        ambiguous = True

                    # verify override action none
                    self.evaluated_keys.append(f"rule/[{idx_rule}]/override_action/[0]/none")
                    override_action = rule.get("override_action")
                    if isinstance(override_action, list) and override_action and isinstance(override_action[0], dict):
                        override_action_none = override_action[0].get("none")
                        if override_action_none and isinstance(override_action_none, list) \
                                and override_action_none and isinstance(override_action_none[0], dict):
                            # definitive PASS
                            found_definitive_pass = True
                        else:
                            # if it's explicitly present in a non-conforming way, we can fail
                            if override_action_none is not None and isinstance(override_action_none, list):
                                # present but not a dict => definitive fail
                                return CheckResult.FAILED
                            # else ambiguous (missing or malformed)
                            ambiguous = True
                    else:
                        ambiguous = True

        if found_definitive_fail:
            return CheckResult.FAILED
        if found_definitive_pass:
            # prefer PASS when we could confidently determine compliance
            return CheckResult.PASSED
        if ambiguous:
            return CheckResult.UNKNOWN
        # no relevant statements found -> previous behavior failed
        return CheckResult.FAILED


check = WAFACLCVE202144228()

