import unittest

from checkov.common.models.enums import CheckResult
from checkov.terraform.checks.resource.aws.WAFACLCVE202144228 import check as ckv_aws_192
from checkov.terraform.checks.resource.aws.WAFRuleHasAnyActions import check as ckv_aws_342


class TestWAFMultipleDynamicRulesPlaceholders(unittest.TestCase):
    def test_ckv_aws_192_multiple_dynamic_rules_unknown(self):
        # conf mimics parser placeholders when multiple dynamic rule blocks exist
        conf = {
            "rule": [
                {"name": [1], "priority": [1], "statement": [1], "action": [1]},  # placeholder rule
                {
                    "name": ["real"],
                    "priority": [10],
                    "statement": [
                        1,  # placeholder inside statements list
                        {
                            "managed_rule_group_statement": [
                                {
                                    "name": ["AWSManagedRulesKnownBadInputsRuleSet"],
                                    "excluded_rule": []
                                }
                            ]
                        }
                    ],
                    "override_action": [
                        {"none": [{}]}
                    ],
                    "action": [{}]
                }
            ]
        }

        result = ckv_aws_192.scan_resource_conf(conf)
        self.assertEqual(result, CheckResult.UNKNOWN)

    def test_ckv_aws_342_multiple_dynamic_rules_unknown(self):
        conf = {
            "rule": [
                {"name": [1], "priority": [1], "statement": [1], "action": [1]},  # placeholder rule
                {
                    "name": ["real"],
                    "priority": [10],
                    "statement": [
                        1,  # placeholder first
                        {"managed_rule_group_statement": [{"name": ["something"]}]}
                    ],
                    "override_action": [
                        {"none": [{}]}
                    ],
                    "action": [{}]
                }
            ]
        }

        result = ckv_aws_342.scan_resource_conf(conf)
        self.assertEqual(result, CheckResult.UNKNOWN)

    def test_ckv_aws_192_all_placeholders_unknown(self):
        conf = {
            "rule": [
                {"name": [1], "priority": [1], "statement": [1], "action": [1]},
                {"name": [1], "priority": [1], "statement": [1], "action": [1]},
            ]
        }
        result = ckv_aws_192.scan_resource_conf(conf)
        self.assertEqual(result, CheckResult.UNKNOWN)

    def test_ckv_aws_342_all_placeholders_unknown(self):
        conf = {
            "rule": [
                {"name": [1], "priority": [1], "statement": [1], "action": [1]},
                {"name": [1], "priority": [1], "statement": [1], "action": [1]},
            ]
        }
        result = ckv_aws_342.scan_resource_conf(conf)
        self.assertEqual(result, CheckResult.UNKNOWN)


if __name__ == '__main__':
    unittest.main()

